#include <iostream>
#include <queue>
#include <vector>
std::vector<int> bfs(const std::vector<std::vector<int>>& graph, int start) {
    std::vector<bool> seen(graph.size(), false); std::vector<int> order; std::queue<int> q;
    seen.at(start) = true; q.push(start);
    while (!q.empty()) { int u=q.front(); q.pop(); order.push_back(u);
        for (int v : graph.at(u)) if (!seen.at(v)) { seen[v]=true; q.push(v); }
    }
    return order;
}
int main() { const std::vector<std::vector<int>> g{{1,2},{0,3},{0},{1}}; for(int n:bfs(g,0)) std::cout << n << ' '; std::cout << '\n'; }
